package com.lqq.supportflow.ticket.api;
import com.lqq.supportflow.shared.AuthenticatedPrincipal; import com.lqq.supportflow.ticket.application.ManageTicketService; import com.lqq.supportflow.ticket.domain.*; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/tickets") public class AdminTicketController { private final ManageTicketService service; public AdminTicketController(ManageTicketService service){this.service=service;} @GetMapping List<Ticket> list(@AuthenticationPrincipal AuthenticatedPrincipal principal){return service.list(principal.tenantId());} @PostMapping("/{ticketId}/claim") Ticket claim(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long ticketId,@RequestHeader("Idempotency-Key") String idempotencyKey){return service.claim(principal.tenantId(),ticketId,principal.membershipId(),idempotencyKey);} @PostMapping("/{ticketId}/status") Ticket status(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long ticketId,@Valid @RequestBody ChangeTicketStatusRequest request){return service.changeStatus(principal.tenantId(),ticketId,request.status());} @GetMapping("/{ticketId}/comments") List<TicketComment> comments(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long ticketId){return service.comments(principal.tenantId(),ticketId);} @PostMapping("/{ticketId}/comments") ResponseEntity<TicketComment> comment(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long ticketId,@Valid @RequestBody TicketCommentRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.addComment(principal.tenantId(),ticketId,principal.membershipId(),request.content()));}}
